                .collect(Collectors.groupingBy(
                        claim -> claim.claimType().trim(),
                        TreeMap::new,
                        Collectors.averagingDouble(claim -> claim.amount().doubleValue())));
    }

    public static List<String> topTypesByTotal(List<Claim> claims, int n) {
        if (n <= 0) {
            return List.of();
        }
        return totalByType(claims).entrySet().stream()
                .sorted(Map.Entry.<String, BigDecimal>comparingByValue(Comparator.reverseOrder())
                        .thenComparing(Map.Entry.comparingByKey()))
                .limit(n)
                .map(Map.Entry::getKey)
                .toList();
